import * as T from 'three';
import {partObject,enclosureObject} from './scene.js';
import {decorateObject,wireObject,texturesReady} from './rendering.js';
import {panels,faceFrame} from './geometry.js';
import {movieState,normalizeMovieOptions} from './movie.js';
const backgrounds={warm:'#e9e5dc',white:'#f2f2f0',dark:'#272c32'};
const disposeTree=root=>{const geometries=new Set(),materials=new Set();root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:[o.material])if(m)materials.add(m);});for(const g of geometries)g.dispose();for(const m of materials)m.dispose();};
export function explosionVector(part,center,scale,index=0){
 if(part.id==='@Base')return new T.Vector3();
 if(part.id?.startsWith('@')){const normal=new T.Vector3(...faceFrame(part.dims,part.face).n);if(part.id!=='@Lid')normal.z=.15;return normal.multiplyScalar(scale*.62);}
 const direction=new T.Vector3(part.pos[0]-center.x,part.pos[1]-center.y,0);if(direction.length()<scale*.07){const a=index*2.399963;direction.set(Math.cos(a),Math.sin(a),0);}direction.normalize().multiplyScalar(scale*.55);direction.z=scale*(.35+.12*(index%3));return direction;
}
export function createMovieModel(project,options){
 const o=normalizeMovieOptions(options),root=new T.Group(),entries=[],wires=new T.Group();const physical=project.parts.filter(p=>p.kind!=='space'&&(o.includeHidden||p.visible));
 try{
 const shell=enclosureObject(project.enclosure,'closed',0,null,project.features);root.add(shell);
 for(const panel of panels(project.enclosure)){const object=shell.children.find(a=>a.userData.partId===panel.id);if(object)entries.push({part:panel,object,panel:true});}
 for(const part of physical){const object=partObject({...part,visible:true});decorateObject(object,part,project.features);root.add(object);entries.push({part,object,panel:false});}
 root.updateMatrixWorld(true);const box=new T.Box3().setFromObject(root);if(box.isEmpty())throw Error('Add physical components or enable an enclosure before exporting a movie.');const center=box.getCenter(new T.Vector3()),scale=Math.max(1,...box.getSize(new T.Vector3()).toArray());
 for(let i=0;i<entries.length;i++){const e=entries[i];e.origin=e.object.position.clone();e.delta=explosionVector(e.part,center,scale,i);e.materials=[];e.object.traverse(node=>{for(const child of [...node.children])if(child.isLineSegments||child.isSprite){node.remove(child);disposeTree(child);}});}
 const present=new Set(physical.map(p=>p.id));for(const w of project.wires)if(w.points.every(pt=>!pt.host||present.has(pt.host)))wires.add(wireObject(project,w));root.add(wires);
 function boundsAt(amount){for(const e of entries)e.object.position.copy(e.origin).addScaledVector(e.delta,amount);root.updateMatrixWorld(true);const b=new T.Box3();for(const e of entries)b.union(new T.Box3().setFromObject(e.object));if(amount===0)b.union(new T.Box3().setFromObject(wires));return b;}
 const assembled=boundsAt(0),exploded=boundsAt(o.explosion);boundsAt(0);
 return {root,entries,wires,scale,assembled,exploded,apply(state){for(const e of entries){e.object.position.copy(e.origin).addScaledVector(e.delta,state.explode);if(e.panel)e.object.traverse(node=>{if(!node.material)return;for(const mat of Array.isArray(node.material)?node.material:[node.material]){const base=mat.userData.movieOpacity??mat.opacity;mat.userData.movieOpacity=base;mat.opacity=base*state.opacity;const transparent=mat.opacity<.999||!!mat.map?.userData?.alpha||!!node.userData.decal;if(mat.transparent!==transparent){mat.transparent=transparent;mat.needsUpdate=true;}mat.depthWrite=!transparent;node.castShadow=state.opacity>.98;}});}this.wires.visible=state.explode<.001;root.updateMatrixWorld(true);},dispose(){disposeTree(root);}};
 }catch(error){disposeTree(root);throw error;}
}
function grainTexture(){const size=256,data=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const grain=Math.sin(y*.38+Math.sin(x*.025)*1.5+Math.sin(y*.07)*2)*.5+Math.sin(y*1.6+x*.009)*.18;const n=Math.round(217+grain*22),i=(y*size+x)*4;data[i]=n;data[i+1]=n;data[i+2]=n;data[i+3]=255;}const texture=new T.DataTexture(data,size,size,T.RGBAFormat);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.magFilter=T.LinearFilter;texture.minFilter=T.LinearMipmapLinearFilter;texture.generateMipmaps=true;texture.needsUpdate=true;return texture;}
function studioEnvironment(renderer){const room=new T.Scene(),back=new T.Mesh(new T.SphereGeometry(25,24,16),new T.MeshBasicMaterial({color:'#737980',side:T.BackSide,toneMapped:false}));room.add(back);const cards=[[-8,-9,12,7,10,5],[10,2,8,4,12,3],[0,8,14,9,5,4],[-2,-1,18,7,6,2]];for(const [x,y,z,w,h,power] of cards){const card=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({color:new T.Color().setScalar(power),side:T.DoubleSide,toneMapped:false}));card.position.set(x,y,z);card.lookAt(0,0,0);room.add(card);}const generator=new T.PMREMGenerator(renderer);const target=generator.fromScene(room,.08,.1,100);generator.dispose();disposeTree(room);return target;}
export function polishMovieMaterials(model,wood){
 for(const e of model.entries){const baseColor=new T.Color(e.part.color);e.object.traverse(node=>{if(!node.isMesh||node.userData.decal)return;const old=Array.isArray(node.material)?node.material:[node.material],next=old.map(m=>{const primary=m.color?.equals(baseColor),isWood=e.part.material==='wood'&&primary,isGlass=e.part.material==='glass'&&primary;const mat=new T.MeshPhysicalMaterial({color:m.color,metalness:m.metalness||0,roughness:isWood?.48:(m.metalness||0)>.4?.24:isGlass?.14:.38,map:m.map||(isWood?wood:null),side:m.side,clearcoat:isWood?.22:isGlass?.5:.15,clearcoatRoughness:.25,transmission:isGlass?.55:0,thickness:isGlass?Math.min(...e.part.dims)*.1:0,ior:1.48,envMapIntensity:1,transparent:m.transparent,opacity:m.opacity});return mat;});node.material=Array.isArray(node.material)?next:next[0];node.castShadow=node.receiveShadow=true;for(const m of old)m.dispose();});}
}
export class MovieStage{
 constructor(project,options,canvas,{preview=false}={}){
  this.options=normalizeMovieOptions(options);this.canvas=canvas;this.preview=preview;this.disposed=false;this.projectFeatures=project.features;this.contextLost=false;this.onContextLost=()=>{this.contextLost=true;};canvas.addEventListener('webglcontextlost',this.onContextLost);
  try{
   this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,preserveDrawingBuffer:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(1);this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.05;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;
   this.scene=new T.Scene();this.scene.background=new T.Color(backgrounds[this.options.background]);this.camera=new T.PerspectiveCamera(34,16/9,.1,50000);this.camera.up.set(0,0,1);this.model=createMovieModel(project,this.options);this.scene.add(this.model.root);this.wood=grainTexture();polishMovieMaterials(this.model,this.wood);this.environment=studioEnvironment(this.renderer);this.scene.environment=this.environment.texture;
   const radius=this.model.scale;this.scene.add(new T.HemisphereLight('#f8f7ee','#a7b4c2',.9));const lights=[[[-1.1,-1.4,2.4],'#fff6e6',4.5],[[1.5,-.1,1.2],'#dfedff',2],[[.1,1.7,1.8],'#ffffff',3]];
   lights.forEach(([pos,color,intensity],i)=>{const light=new T.DirectionalLight(color,intensity);light.position.fromArray(pos).multiplyScalar(radius);light.target.position.copy(this.model.assembled.getCenter(new T.Vector3()));this.scene.add(light,light.target);if(i===0){light.castShadow=true;const range=radius*(2+this.options.explosion);Object.assign(light.shadow.camera,{left:-range,right:range,top:range,bottom:-range,near:.1,far:range*5});const size=!preview&&this.options.quality==='high'?4096:2048;light.shadow.mapSize.set(size,size);light.shadow.bias=-.0001;light.shadow.normalBias=radius*.0005;light.shadow.radius=3;this.keyLight=light;}});
   const floor=new T.Mesh(new T.PlaneGeometry(radius*100,radius*100),new T.MeshStandardMaterial({color:backgrounds[this.options.background],roughness:.65,metalness:.04}));floor.position.z=this.model.assembled.min.z-radius*.008;floor.receiveShadow=true;this.scene.add(floor);this.floor=floor;
   this.render(0);
  }catch(e){this.dispose();throw e;}
 }
 async ready(){await texturesReady(this.projectFeatures);if(this.disposed)throw Error('Movie scene was closed.');}
 setSize(width,height){const gl=this.renderer.getContext(),max=Math.min(this.renderer.capabilities.maxTextureSize,gl.getParameter(gl.MAX_RENDERBUFFER_SIZE));if(width>max||height>max)throw Error('This GPU cannot render the requested quality. Choose Standard or 720p.');this.renderer.setSize(width,height,false);if(gl.drawingBufferWidth!==width||gl.drawingBufferHeight!==height)throw Error('The graphics device could not allocate a full movie frame. Choose Standard or 720p.');this.camera.aspect=width/height;this.camera.updateProjectionMatrix();}
 render(time){if(this.disposed)return;if(this.contextLost||this.renderer.getContext().isContextLost())throw Error('The graphics device ran out of resources. Reload and try 720p / Standard quality.');const state=movieState(time,this.options);this.model.apply(state);const fraction=state.explode/this.options.explosion,box=new T.Box3(this.model.assembled.min.clone().lerp(this.model.exploded.min,fraction),this.model.assembled.max.clone().lerp(this.model.exploded.max,fraction)),sphere=box.getBoundingSphere(new T.Sphere()),target=sphere.center;const halfFov=Math.min(this.camera.fov*Math.PI/360,Math.atan(Math.tan(this.camera.fov*Math.PI/360)*this.camera.aspect));const distance=sphere.radius/Math.sin(halfFov)*1.16*(1-state.hero*.07),a=-.92+state.azimuth,elevation=this.options.elevation*Math.PI/180;this.camera.position.set(target.x+Math.cos(a)*Math.cos(elevation)*distance,target.y+Math.sin(a)*Math.cos(elevation)*distance,target.z+Math.sin(elevation)*distance);this.camera.near=Math.max(.01,distance/1000);this.camera.far=distance+this.model.scale*30;this.camera.lookAt(target);this.camera.updateProjectionMatrix();this.renderer.render(this.scene,this.camera);return state;}
 dispose(){if(this.disposed)return;this.disposed=true;this.canvas?.removeEventListener('webglcontextlost',this.onContextLost);this.model?.dispose();if(this.floor)disposeTree(this.floor);this.keyLight?.shadow?.map?.dispose();this.environment?.dispose();this.wood?.dispose();this.renderer?.dispose();this.renderer?.forceContextLoss();}
}
